"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def uniqueIPs(ipList):
    seen = set()
    uniqueList = []
    for ip in ipList:
        if (ip not in seen):
            seen.add(ip)
            uniqueList.append(ip)
    return uniqueList
print(uniqueIPs(["192.168.1.1", "192.168.1.2", "192.168.1.1"]))